请对以下 case 进行三维加权评分。

=== case_id ===
Case-01-low-power-015

=== 用户原始指令 (query.txt) ===
晚上睡前手机经常只剩30%多,第二天起床怕没电。做个卡片纵向堆叠显示当前电量、明早天气、闹钟时间几个信息。卡片内嵌小面板,点卡片能跳到闹钟应用。浅色调底色,用夜晚的深蓝紫色渐变。电量低于30%时显示橙色待处理。底部横向排几个常用图标。

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "晚上睡前手机经常只剩30%多,第二天起床怕没电。做个卡片纵向堆叠显示当前电量、明早天气、闹钟时间几个信息。卡片内嵌小面板,点卡片能跳到闹钟应用。浅色调底色,用夜晚的深蓝紫色渐变。电量低于30%时显示橙色待处理。底部横向排几个常用图标。",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.huawei.hmos.clock",
        "abilityName": "com.huawei.hmos.clock.phone",
        "uri": ""
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "battery": {
        "percentText": {
          "type": "string",
          "description": "当前手机电量百分比展示文本。",
          "sampleValue": "32%"
        },
        "percentValue": {
          "type": "number",
          "description": "当前手机电量百分比数值，用于进度条。",
          "sampleValue": 32
        },
        "statusText": {
          "type": "string",
          "description": "低电量状态提示，低于30%时显示待处理提醒。",
          "sampleValue": "电量偏低"
        },
        "statusColor": {
          "type": "string",
          "description": "电量状态文字颜色，低于30%时使用橙色警示色。",
          "sampleValue": "#ffe84026"
        }
      },
      "weather": {
        "daily": [
          {
            "weekday": {
              "type": "string",
              "description": "明早天气对应的日期提示。",
              "sampleValue": "明早"
            },
            "condition": {
              "type": "string",
              "description": "明早天气现象。",
              "sampleValue": "多云"
            },
            "temperatureRangeText": {
              "type": "string",
              "description": "明早温度范围展示文本。",
              "sampleValue": "24°/31°"
            }
          }
        ]
      },
      "alarm": {
        "timeText": {
          "type": "string",
          "description": "下一次闹钟时间展示文本。",
          "sampleValue": "07:30"
        }
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_electricity.png",
      "description": "电池图标，适合低电模式卡片中表示当前电量。"
    },
    {
      "src": "resources/base/media/partly_cloudy.png",
      "description": "彩色多云天气图标，适合展示明早天气。"
    },
    {
      "src": "resources/base/media/icon_alarm_clock.png",
      "description": "闹钟图标，适合表示闹钟时间和跳转闹钟应用入口。"
    },
    {
      "src": "resources/base/media/icon_charge.png",
      "description": "充电闪电图标，适合底部常用图标中表示充电。"
    },
    {
      "src": "resources/base/media/icon_save_power.png",
      "description": "省电图标，适合底部常用图标中表示低电模式或省电建议。"
    }
  ]
}

